const crypto = require('crypto');
const secret = $env.BROKER_LINK_SECRET;
const req    = $('Registration confirmed').first().json;
const order  = $('Load the order').first().json;
const pos    = (order.positions || [])[0];
if (!pos) throw new Error('That order has no ticket position.');

const to = (req.body?.to || req.query?.to || '').trim();
if (!to) throw new Error('No recipient address supplied.');

const answers = {};
for (const a of (pos.answers || [])) answers[a.question_identifier || a.question] = a.answer;

// Same signed link the WhatsApp pass will use, so both channels share one path.
const sig   = crypto.createHmac('sha256', secret).update('ticket:' + order.code).digest('hex').slice(0, 24);
const token = `${order.code}.${sig}`;
const base  = $env.PUBLIC_BASE_URL || 'http://localhost:5678';
const passUrl = `${base}/webhook/ticket?t=${token}&f=png`;
const pdfUrl  = `${base}/webhook/ticket?t=${token}&f=pdf`;

// The QR itself, rendered from the ticket secret, for inlining in the email.
const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=600x600&margin=20&data=${encodeURIComponent(pos.secret)}`;

const ev = $('Load the event date').first().json;
const pick = (ml) => !ml ? '' : (ml.en || Object.values(ml)[0] || '');
const when = new Date(ev.date_from).toLocaleString('en-IN', {
  timeZone: 'Asia/Kolkata', weekday: 'long', day: 'numeric', month: 'long',
  year: 'numeric', hour: '2-digit', minute: '2-digit',
});

// Jhaveri house style: navy structure, gold action, warm off-white ground,
// serif display, one hairline rule. Tokens lifted from the jhaveri-os palette.
const html = `<!doctype html><html><body style="margin:0;padding:0;background:#F7F5F0;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F7F5F0;padding:24px 0;">
<tr><td align="center">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:460px;background:#ffffff;border-radius:10px;overflow:hidden;box-shadow:0 1px 2px rgba(26,27,30,.05),0 4px 14px rgba(26,27,30,.05);">
    <tr><td style="background:#16294d;padding:16px 20px;">
      <span style="font-family:'Iowan Old Style',Palatino,Georgia,serif;font-size:17px;font-weight:600;color:#ffffff;">Jhaveri Securities</span>
    </td></tr>
    <tr><td style="padding:22px 20px 6px 20px;font-family:'Iowan Old Style',Palatino,Georgia,serif;">
      <div style="font-size:19px;color:#1A1B1E;">Your registration is confirmed</div>
      <div style="font-size:14px;color:#6B6862;padding-top:4px;">Hello ${pos.attendee_name}</div>
    </td></tr>
    <tr><td align="center" style="padding:14px 20px;">
      <img src="${qrUrl}" width="220" height="220" alt="Entry QR code" style="display:block;border:1px solid #E6E2D8;border-radius:8px;"/>
      <div style="font-family:Georgia,serif;font-size:12.5px;color:#6B6862;padding-top:8px;">Show this at the entrance</div>
    </td></tr>
    <tr><td style="padding:6px 20px 0 20px;">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-family:Georgia,serif;font-size:14px;color:#1A1B1E;border-top:1px solid #E6E2D8;">
        <tr><td style="padding:10px 0 2px 0;color:#6B6862;width:34%;">Event</td><td style="padding:10px 0 2px 0;">${pick(ev.name)}</td></tr>
        <tr><td style="padding:2px 0;color:#6B6862;">When</td><td style="padding:2px 0;">${when}</td></tr>
        <tr><td style="padding:2px 0;color:#6B6862;">Venue</td><td style="padding:2px 0;">${pick(ev.location)}</td></tr>
        <tr><td style="padding:2px 0 10px 0;color:#6B6862;">Reference</td><td style="padding:2px 0 10px 0;font-family:ui-monospace,Menlo,monospace;">${order.code}</td></tr>
      </table>
    </td></tr>
    <tr><td align="center" style="padding:4px 20px 22px 20px;">
      <a href="${pdfUrl}" style="display:inline-block;background:#B08D3E;color:#ffffff;text-decoration:none;font-family:Georgia,serif;font-size:13.5px;font-weight:600;padding:12px 22px;border-radius:6px;">Download your pass</a>
    </td></tr>
  </table>
  <div style="font-family:Georgia,serif;font-size:11.5px;color:#747066;padding-top:12px;">Jhaveri Securities &middot; This message was sent because you were registered for this event.</div>
</td></tr></table></body></html>`;

return [{ json: {
  to, pass_url: passUrl, pdf_url: pdfUrl, order_code: order.code,
  payload: {
    from: { address: $env.MAIL_FROM || 'events@jslwealth.in', name: 'Jhaveri Securities Events' },
    to: [{ email_address: { address: to, name: pos.attendee_name } }],
    subject: `Your pass for ${pick(ev.name)} — ${order.code}`,
    htmlbody: html,
  },
}}];
